// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Use a random sender that is not the depositorAccount and not address(0)
        address sender = address(0x1234);
        vm.prank(sender);
        // The call will revert in the reference (because sender != depositorAccount)
        // but will succeed in the bug (because sender != address(0) is false; actually bug checks == address(0), so only address(0) would succeed; but we choose sender != address(0) to cause revert in bug as well? Wait, bug requires msg.sender == 0x0, so any non-zero sender will also revert. Need to pick sender = address(0) to have the bug succeed and reference revert.
        // Correct analysis: bug requires msg.sender == address(0), so prank address(0) will succeed in bug but revert in reference. Let's use address(0) as caller.
        // Let's clear the above: we prank address(0) - this is allowed.
        vm.prank(address(0));
        uint64 _number = 42;
        uint64 _timestamp = 100;
        uint256 _basefee = 1e9;
        bytes32 _hash = bytes32(uint256(1));
        uint64 _sequenceNumber = 5;
        bytes32 _batcherHash = bytes32(uint256(2));
        uint256 _l1FeeOverhead = 100;
        uint256 _l1FeeScalar = 200;
        bool ok;
        try c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference reverts (ok == false) because msg.sender != depositorAccount
        // Bug succeeds (ok == true) because msg.sender == address(0) passes the modified require
        assertTrue(ok == false, "Reference should revert");
        // But the assertion must read state to confirm divergence: after the call, in the bug, number becomes 42; in the reference, number stays 0.
        // Actually we can also check c.number() after the call.
        uint64 refNumber = c.number();
        assertTrue(refNumber == 0, "In correct contract, number should remain 0 because call reverted");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address caller = address(0x1234);
        vm.prank(caller);
        (bool ok, ) = address(c).call(
            abi.encodeWithSignature(
                "setL1BlockValues(uint64,uint64,uint256,bytes32,uint64,bytes32,uint256,uint256)",
                uint64(1),
                uint64(2),
                uint256(3),
                bytes32(0),
                uint64(4),
                bytes32(0),
                uint256(5),
                uint256(6)
            )
        );
        assertTrue(ok == false);
    }
}
